// Compute the forward (z), right (x) and up (y) vectors of the camera coordinate system
vec3 z = normalized(eye - center);
vec3 x = normalized(cross(up, z));
vec3 y = normalized(cross(z, x));

// Create the rotation matrix (inverse of the camera's rotation)
mat<4,4> rotation = {{{x.x, x.y, x.z, 0},
                      {y.x, y.y, y.z, 0},
                      {z.x, z.y, z.z, 0},
                      {0,   0,   0,   1}}};

// Create the translation matrix (inverse of the camera's translation)
mat<4,4> translation = {{{1, 0, 0, -eye.x},
                         {0, 1, 0, -eye.y},
                         {0, 0, 1, -eye.z},
                         {0, 0, 0, 1}}};

// The lookat matrix is the product of rotation and translation
return rotation * translation;

